    let depth = 0;
    let inSingleQuote = false;
    let inDoubleQuote = false;
    let escape = false;

    for (let i = 0; i < content.length; i++) {
      const char = content[i];

      if (escape) {
        current += char;
        escape = false;
        continue;
      }

      if (inDoubleQuote) {
        current += char;
        if (char === '\\') {
          escape = true;
        } else if (char === '"') {
          inDoubleQuote = false;
        }
        continue;
      }

