        current += char;
        inDoubleQuote = true;
      } else if (char === "'") {
        current += char;
        inSingleQuote = true;
      } else if (char === '[' || char === '{') {
        current += char;
        depth++;
      } else if (char === ']' || char === '}') {
        current += char;
        depth--;
      } else if (char === ',' && depth === 0) {
