      const line = this.lines[i];

      // Skip comments and blank lines
      const trimmed = this.getCommentStart(line);
      if (trimmed.length === 0) {
        continue;
      }

      // Check for header
      if (trimmed[0] === '[') {
        this.parseHeader(trimmed, lineNum);
      } else {
        // Parse key-value pair
        this.parseKeyValue(trimmed, lineNum);
      }
    }

    return this.root;
  }

  // Find where a comment starts (# or ; outside quoted strings)
  getCommentStart(line) {
    let result = '';
    let inSingleQuote = false;
    let inDoubleQuote = false;
    let escape = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];

      if (escape) {
        result += char;
        escape = false;
        continue;
      }

      if (inDoubleQuote) {
        result += char;
        if (char === '\\') {
          escape = true;
        } else if (char === '"') {
          inDoubleQuote = false;
        }
        continue;
      }

      if (inSingleQuote) {
        result += char;
        if (char === "'") {
          inSingleQuote = false;
        }
        continue;
      }

      if (char === '"') {
        result += char;
        inDoubleQuote = true;
      } else if (char === "'") {
        result += char;
        inSingleQuote = true;
      } else if (char === '#' || char === ';') {
        break;
      } else {
        result += char;
      }
