  if (Array.isArray(obj)) {
    lines.push(path + ' array');
    for (let i = 0; i < obj.length; i++) {
      const itemPath = path + '[' + i + ']';
      const item = obj[i];
      if (typeof item === 'object' && item !== null) {
        walkKeys(item, itemPath, lines);
      } else {
        const type = typeof item === 'boolean' ? 'boolean' : 
                     typeof item === 'number' ? (Number.isInteger(item) ? 'integer' : 'float') :
                     typeof item === 'string' ? 'string' : 'unknown';
        lines.push(itemPath + ' ' + type);
      }
    }
  } else if (typeof obj === 'object' && obj !== null) {
    // It's a table
    const keys = Object.keys(obj).sort((a, b) => {
      // Sort by code point
      return a < b ? -1 : a > b ? 1 : 0;
    });

    // First emit the table itself if path is not empty
    if (path.length > 0) {
      lines.push(path + ' table');
    }

    for (const key of keys) {
      const value = obj[key];
      const itemPath = path.length > 0 ? path + '.' + key : key;

      if (typeof value === 'object' && value !== null) {
        walkKeys(value, itemPath, lines);
      } else {
        const type = typeof value === 'boolean' ? 'boolean' :
                     typeof value === 'number' ? (Number.isInteger(value) ? 'integer' : 'float') :
                     typeof value === 'string' ? 'string' : 'unknown';
        lines.push(itemPath + ' ' + type);
      }
    }
  }
}
