    let inSingleQuote = false;
    let inDoubleQuote = false;
    let escape = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];

      if (escape) {
        result += char;
        escape = false;
        continue;
      }

      if (inDoubleQuote) {
        result += char;
        if (char === '\\') {
          escape = true;
        } else if (char === '"') {
          inDoubleQuote = false;
        }
        continue;
      }

      if (inSingleQuote) {
        result += char;
        if (char === "'") {
          inSingleQuote = false;
        }
        continue;
      }

      if (char === '"') {
        result += char;
        inDoubleQuote = true;
      } else if (char === "'") {
        result += char;
        inSingleQuote = true;
      } else if (char === '#' || char === ';') {
        break;
      } else {
        result += char;
      }
    }

    return result.trimEnd();
  }

  parseHeader(line, lineNum) {
    if (line[0] !== '[') {
      throw new ParseError(lineNum, 'expected a name');
    }

