    if (valuePart.length === 0) {
      throw new ParseError(lineNum, 'expected a value');
    }

    const names = this.parseDottedName(keyPart, lineNum);
    const value = this.parseValue(valuePart, lineNum);

    // Navigate/create the path
    let current = this.current;
    let path = [...this.currentPath];

    for (let i = 0; i < names.length - 1; i++) {
      const name = names[i];
