      const char = line[i];

      if (escape) {
        result += char;
        escape = false;
        continue;
      }

      if (inDoubleQuote) {
        result += char;
        if (char === '\\') {
          escape = true;
        } else if (char === '"') {
          inDoubleQuote = false;
        }
        continue;
      }

      if (inSingleQuote) {
        result += char;
        if (char === "'") {
          inSingleQuote = false;
        }
        continue;
      }

      if (char === '"') {
        result += char;
        inDoubleQuote = true;
      } else if (char === "'") {
        result += char;
        inSingleQuote = true;
      } else if (char === '#' || char === ';') {
